INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f09b91aa-91ce-53f3-8294-a1207d8e576e', 'Ghana Corporate Governance Manual for Governing Boards/Council of the', 'Corporate Governance Manual for Governing Boards/Council of the Ghana Public Services', 'The Public Services Commission has developed this Manual to streamline corporate governance practices. It is expected that the implementation of this manual will accomplish the following: Improved strategic direction of public service organizations; Enhanced appreciation of the duties and responsibilities of a Board/Council member; Strengthened oversight responsibilities of Governing Boards/Councils; Improved relationship between Boards/Councils and Management and staff; Increased responsibility, transparency, accountability, efficiency and effectiveness; Adherence to set guidelines and standards; Effective and efficient management of the organization for the achievement of the stated objectives; Improved risk management
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ca3aa11b-6747-5981-8fd6-09bcd8638c57', 'Ghana Biosafety Act 831', 'Biosafety Act 831', 'The objectives of the Act are, (a) to ensure an adequate level of protection in the field of safe development transfer, handling and use of genetically modified organisms resulting from biotechnology that may have an adverse effect on health and the environment, and (b) to establish a transparent an d predicta ble process to review and make decisions on genetically modified organisms specified in paragraph raj and related activities.', 'The objectives of the Act are, (a) to ensure an adequate level of protection in the field of safe development transfer, handling and use of genetically modified organisms resulting from biotechnology that may have an adverse effect on health and the environment, and (b) to establish a transparent an d predicta ble process to review and make decisions on genetically modified organisms specified in paragraph raj and related activities.', 'The objectives of the Act are, (a) to ensure an adequate level of protection in the field of safe development transfer, handling and use of genetically modified organisms resulting from biotechnology that may have an adverse effect on health and the environment, and (b) to establish a transparent an d predicta ble process to review and make decisions on genetically modified organisms specified in paragraph raj and related activities.', 'Ghana', 'nature', 'in_force', '2011-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_12', ARRAY['sdg2', 'sdg14', 'other sustainability policy', 'regulations', 'mandatory', 'sdg3', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9a2a5481-1585-5de3-9377-cf25cfe4708d', 'Ghana Corporate Governance Guidelines on Best Practices', 'Corporate Governance Guidelines on Best Practices - 2009', 'The Commission has considered it appropriate to issue guidance notes on the manner in which taking into consideration, the state of development of the market in Ghana, the regulatory framework and the domestic corporate culture and circumstance, the principles of corporate governance could be implemented in the Ghanaia in context.', 'The Commission has considered it appropriate to issue guidance notes on the manner in which taking into consideration, the state of development of the market in Ghana, the regulatory framework and the domestic corporate culture and circumstance, the principles of corporate governance could be implemented in the Ghanaia in context.', 'The Commission has considered it appropriate to issue guidance notes on the manner in which taking into consideration, the state of development of the market in Ghana, the regulatory framework and the domestic corporate culture and circumstance, the principles of corporate governance could be implemented in the Ghanaia in context.', 'Ghana', 'climate', 'in_force', '2009-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_3', ARRAY['sdg2', 'sdg3', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'sdg16', 'sdg9', 'voluntary', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6a8f7ee2-5011-5b6e-a3dc-0d890b5b8be8', 'Ghana Management of ozone depleting substances and products regulations', 'Management of ozone depleting substances and products regulations', 'The Management of Ozone Depleting Substances and Products Regulations in Ghana, enacted in 2005, aims to regulate the import, export, and manufacturing of substances and products that contribute to ozone depletion. The policy establishes permit requirements, conditions, and reporting procedures to ensure compliance and prevent environmental harm. It includes restrictions on trade, permit application processes, non-transferability of permits, and a complaints resolution mechanism. The policy targets companies involved in importing, exporting, and manufacturing substances and products containing controlled substances specified in the regulations.', 'The Management of Ozone Depleting Substances and Products Regulations in Ghana, enacted in 2005, aims to regulate the import, export, and manufacturing of substances and products that contribute to ozone depletion. The policy establishes permit requirements, conditions, and reporting procedures to ensure compliance and prevent environmental harm. It includes restrictions on trade, permit application processes, non-transferability of permits, and a complaints resolution mechanism. The policy targets companies involved in importing, exporting, and manufacturing substances and products containing controlled substances specified in the regulations.', 'The Management of Ozone Depleting Substances and Products Regulations in Ghana, enacted in 2005, aims to regulate the import, export, and manufacturing of substances and products that contribute to ozone depletion. The policy establishes permit requirements, conditions, and reporting procedures to ensure compliance and prevent environmental harm. It includes restrictions on trade, permit application processes, non-transferability of permits, and a complaints resolution mechanism. The policy targets companies involved in importing, exporting, and manufacturing substances and products containing controlled substances specified in the regulations.', 'Ghana', 'climate', 'in_force', '2005-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_13', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg9', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c7cdb2be-c81d-5f1c-b3b6-1148fb1a1bd6', 'Ghana Environmental Assessment Regulations', 'Environmental Assessment Regulations', 'This document outlines the environmental assessment regulations. This includes requirements around registration, issuing environmental permits, environmental impact assessment, screening report, and fees for and publication of grants of environmental permits.', 'This document outlines the environmental assessment regulations. This includes requirements around registration, issuing environmental permits, environmental impact assessment, screening report, and fees for and publication of grants of environmental permits.', 'This document outlines the environmental assessment regulations. This includes requirements around registration, issuing environmental permits, environmental impact assessment, screening report, and fees for and publication of grants of environmental permits.', 'Ghana', 'climate', 'in_force', '1999-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_10', ARRAY['mandatory', 'other sustainability policy', 'ghana', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d77932c8-8747-56ac-8ecf-3639868d919d', 'GRI 102 Climate Change', 'GRI 102 Climate Change 2025', 'GRI 102: Climate Change 2025 establishes a standardized, voluntary framework for organizations to report their climate-related impacts, risks, and actions. Effective from 1 January 2026, the standard guides companies in disclosing their governance, strategy, targets, and transition plans related to climate change. Developed by the GSSB, it aligns with international frameworks like the TCFD and the Paris Agreement, emphasizing transparency around GHG emissions, climate-related risks, and climate adaptation efforts. Organizations must report how they engage with stakeholders, develop climate policies, and manage impacts across their operations and value chains. The standard supports integrated, science-based climate action and encourages disclosures about just transition, energy efficiency, and supply chain risks. Although not legally binding, GRI 102 enhances the comparability and quality of climate disclosures for investors and regulators. It provides organizations with tools to improve accountability, reduce emissions, and align their sustainability strategies with global climate objectives.', 'GRI 102: Climate Change 2025 establishes a standardized, voluntary framework for organizations to report their climate-related impacts, risks, and actions. Effective from 1 January 2026, the standard guides companies in disclosing their governance, strategy, targets, and transition plans related to climate change. Developed by the GSSB, it aligns with international frameworks like the TCFD and the Paris Agreement, emphasizing transparency around GHG emissions, climate-related risks, and climate adaptation efforts. Organizations must report how they engage with stakeholders, develop climate policies, and manage impacts across their operations and value chains. The standard supports integrated, science-based climate action and encourages disclosures about just transition, energy efficiency, and supply chain risks. Although not legally binding, GRI 102 enhances the comparability and quality of climate disclosures for investors and regulators. It provides organizations with tools to improve accountability, reduce emissions, and align their sustainability strategies with global climate objectives.', 'GRI 102: Climate Change 2025 establishes a standardized, voluntary framework for organizations to report their climate-related impacts, risks, and actions. Effective from 1 January 2026, the standard guides companies in disclosing their governance, strategy, targets, and transition plans related to climate change. Developed by the GSSB, it aligns with international frameworks like the TCFD and the Paris Agreement, emphasizing transparency around GHG emissions, climate-related risks, and climate adaptation efforts. Organizations must report how they engage with stakeholders, develop climate policies, and manage impacts across their operations and value chains. The standard supports integrated, science-based climate action and encourages disclosures about just transition, energy efficiency, and supply chain risks. Although not legally binding, GRI 102 enhances the comparability and quality of climate disclosures for investors and regulators. It provides organizations with tools to improve accountability, reduce emissions, and align their sustainability strategies with global climate objectives.', 'GRI', 'climate', 'in_force', '2025-01-01'::date, 'Global Reporting Initiative', 'https://globalreporting.org/media/qadh4mpf/gri-102-climate-change-2025-frequently-asked-questions-faqs.pdf', ARRAY['sdg13', 'regulations', 'sdg7', 'sdg16', 'gri', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b560995b-0cf5-5513-b40b-7516df757756', 'GRI 103 Energy', 'GRI 103 Energy 2025', 'GRI 103: Energy 2025 is a voluntary sustainability reporting standard focused on how organizations consume and manage energy across their operations and value chains. Developed by the GSSB, it becomes effective on 1 January 2027 and includes disclosures on energy policies, consumption, self-generation, upstream and downstream energy use, and energy intensity. It encourages companies to align with global climate goals by reducing GHG emissions, improving energy efficiency, and transitioning to renewable sources. The standard outlines both positive and negative impacts of energy practices on people and the environment, and supports transparency around energy use, transition planning, and stakeholder engagement. Organizations are encouraged to integrate just transition principles and to disclose targets, investments, and risk mitigation measures. While not mandatory, GRI 103: Energy 2025 enhances accountability, benchmarking, and stakeholder trust through structured, science-based energy reporting practices aligned with international sustainability objectives.', 'GRI 103: Energy 2025 is a voluntary sustainability reporting standard focused on how organizations consume and manage energy across their operations and value chains. Developed by the GSSB, it becomes effective on 1 January 2027 and includes disclosures on energy policies, consumption, self-generation, upstream and downstream energy use, and energy intensity. It encourages companies to align with global climate goals by reducing GHG emissions, improving energy efficiency, and transitioning to renewable sources. The standard outlines both positive and negative impacts of energy practices on people and the environment, and supports transparency around energy use, transition planning, and stakeholder engagement. Organizations are encouraged to integrate just transition principles and to disclose targets, investments, and risk mitigation measures. While not mandatory, GRI 103: Energy 2025 enhances accountability, benchmarking, and stakeholder trust through structured, science-based energy reporting practices aligned with international sustainability objectives.', 'GRI 103: Energy 2025 is a voluntary sustainability reporting standard focused on how organizations consume and manage energy across their operations and value chains. Developed by the GSSB, it becomes effective on 1 January 2027 and includes disclosures on energy policies, consumption, self-generation, upstream and downstream energy use, and energy intensity. It encourages companies to align with global climate goals by reducing GHG emissions, improving energy efficiency, and transitioning to renewable sources. The standard outlines both positive and negative impacts of energy practices on people and the environment, and supports transparency around energy use, transition planning, and stakeholder engagement. Organizations are encouraged to integrate just transition principles and to disclose targets, investments, and risk mitigation measures. While not mandatory, GRI 103: Energy 2025 enhances accountability, benchmarking, and stakeholder trust through structured, science-based energy reporting practices aligned with international sustainability objectives.', 'GRI', 'climate', 'in_force', '2025-01-01'::date, 'Global Reporting Initiative', 'https://globalreporting.org/media/mead5ytn/gri-103-energy-2025-frequently-asked-questions-faqs.pdf', ARRAY['sdg13', 'regulations', 'sdg7', 'sdg17', 'sdg16', 'gri', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('783a1841-6089-5352-b41e-2668a95a36d7', 'GRI Topic Standard Project GRI 103: Energy', 'GRI Topic Standard Project GRI 103: Energy 2025', 'This policy was published in 2025 by Global Reporting Initiative (GRI). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Global Reporting Initiative (GRI). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Global Reporting Initiative (GRI). It addresses sustainability and corporate responsibility requirements.', 'GRI', 'climate', 'in_force', '2025-01-01'::date, 'Global Reporting Initiative', 'https://globalreporting.org/media/mead5ytn/gri-103-energy-2025-frequently-asked-questions-faqs.pdf', ARRAY['sdg7', 'voluntary_frameworks', 'voluntary', 'gri']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4776e6e3-bdca-5911-af1f-354fdf3d6047', 'GRI 14 Mining Sector', 'GRI 14 Mining Sector 2024', 'GRI 101: Biodiversity 2024 sets out voluntary sustainability reporting standards focused on biodiversity-related impacts for organizations. Developed by the Global Sustainability Standards Board (GSSB), it aims to improve disclosures related to how organizations affect and manage biodiversity across their operations and supply chains. The standard includes guidance on policies, practices, and performance indicators related to biodiversity conservation, land use, and ecosystem impacts. Organizations are expected to disclose how they identify material biodiversity topics, what goals they‚Äôve set, and how they measure progress. The document provides specific templates and indicators for biodiversity disclosures, encouraging organizations to align with global biodiversity commitments like the Kunming-Montreal Global Biodiversity Framework. Although it is not legally binding, it serves as a widely adopted framework that encourages transparency and comparability in biodiversity reporting. GRI 101: Biodiversity 2024 becomes effective on 1 January 2026 and supports users in enhancing their biodiversity management strategies through improved sustainability reporting practices.', 'GRI 101: Biodiversity 2024 sets out voluntary sustainability reporting standards focused on biodiversity-related impacts for organizations. Developed by the Global Sustainability Standards Board (GSSB), it aims to improve disclosures related to how organizations affect and manage biodiversity across their operations and supply chains. The standard includes guidance on policies, practices, and performance indicators related to biodiversity conservation, land use, and ecosystem impacts. Organizations are expected to disclose how they identify material biodiversity topics, what goals they‚Äôve set, and how they measure progress. The document provides specific templates and indicators for biodiversity disclosures, encouraging organizations to align with global biodiversity commitments like the Kunming-Montreal Global Biodiversity Framework. Although it is not legally binding, it serves as a widely adopted framework that encourages transparency and comparability in biodiversity reporting. GRI 101: Biodiversity 2024 becomes effective on 1 January 2026 and supports users in enhancing their biodiversity management strategies through improved sustainability reporting practices.', 'GRI 101: Biodiversity 2024 sets out voluntary sustainability reporting standards focused on biodiversity-related impacts for organizations. Developed by the Global Sustainability Standards Board (GSSB), it aims to improve disclosures related to how organizations affect and manage biodiversity across their operations and supply chains. The standard includes guidance on policies, practices, and performance indicators related to biodiversity conservation, land use, and ecosystem impacts. Organizations are expected to disclose how they identify material biodiversity topics, what goals they‚Äôve set, and how they measure progress. The document provides specific templates and indicators for biodiversity disclosures, encouraging organizations to align with global biodiversity commitments like the Kunming-Montreal Global Biodiversity Framework. Although it is not legally binding, it serves as a widely adopted framework that encourages transparency and comparability in biodiversity reporting. GRI 101: Biodiversity 2024 becomes effective on 1 January 2026 and supports users in enhancing their biodiversity management strategies through improved sustainability reporting practices.', 'GRI', 'climate', 'in_force', '2024-01-01'::date, 'INCP', 'https://incp.org.co/wp-content/uploads/2024/02/GRI-14-Sector-minero-2024.pdf', ARRAY['regulations', 'sdg16', 'gri', 'sdg12', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d2f4c35b-e123-5c99-840b-8515c8e67e0f', 'GRI 12: Coal Sector', 'GRI 12: Coal Sector 2022', 'GRI 12: Coal Sector 2022 provides information for organizations in the coal sector about their likely material topics. These topics are likely to be material for organizations in the coal sector on the basis of the sector’s most significant impacts on the economy, environment, and people, including on their human rights. GRI 12 also contains a list of disclosures for organizations in the coal sector to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI 12: Coal Sector 2022 provides information for organizations in the coal sector about their likely material topics. These topics are likely to be material for organizations in the coal sector on the basis of the sector’s most significant impacts on the economy, environment, and people, including on their human rights. GRI 12 also contains a list of disclosures for organizations in the coal sector to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI 12: Coal Sector 2022 provides information for organizations in the coal sector about their likely material topics. These topics are likely to be material for organizations in the coal sector on the basis of the sector’s most significant impacts on the economy, environment, and people, including on their human rights. GRI 12 also contains a list of disclosures for organizations in the coal sector to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI', 'climate', 'in_force', '2022-01-01'::date, 'Global Reporting Initiative', 'https://www.globalreporting.org/media/lm5fcrpc/gri12_coalsector_2022_faqs.pdf', ARRAY['regulations', 'sdg16', 'gri', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0d6ebb88-6a6f-5337-a09d-0dd1d0f1fd69', 'GRI 13: Agriculture, Aquaculture and Fishing Sectors', 'GRI 13: Agriculture, Aquaculture and Fishing Sectors 2022', 'GRI 13: Agriculture, Aquaculture and Fishing Sectors 2022 provides information for organizations in the agriculture, aquaculture, and fishing sectors about their likely material topics. These topics are likely to be material for organizations in the sectors on the basis of the sectors’ most significant impacts on the economy, environment, and people, including on their human rights. GRI 13 also contains a list of disclosures for organizations in the agriculture, aquaculture, and fishing sectors to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI 13: Agriculture, Aquaculture and Fishing Sectors 2022 provides information for organizations in the agriculture, aquaculture, and fishing sectors about their likely material topics. These topics are likely to be material for organizations in the sectors on the basis of the sectors’ most significant impacts on the economy, environment, and people, including on their human rights. GRI 13 also contains a list of disclosures for organizations in the agriculture, aquaculture, and fishing sectors to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI 13: Agriculture, Aquaculture and Fishing Sectors 2022 provides information for organizations in the agriculture, aquaculture, and fishing sectors about their likely material topics. These topics are likely to be material for organizations in the sectors on the basis of the sectors’ most significant impacts on the economy, environment, and people, including on their human rights. GRI 13 also contains a list of disclosures for organizations in the agriculture, aquaculture, and fishing sectors to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI', 'climate', 'in_force', '2022-01-01'::date, 'Global Reporting Initiative', 'https://www.globalreporting.org/media/i0jjkpze/gri13_aafsectors_2022_faqs_post-launch.pdf', ARRAY['sdg2', 'sdg14', 'regulations', 'sdg16', 'gri', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('79e9d6ff-312c-5042-890d-736b7bf3778f', 'GRI 1: Foundation', 'GRI 1: Foundation 2021', 'GRI 1: Foundation 2021 introduces the purpose and system of the GRI Sustainability Reporting Standards (GRI Standards) and explains key concepts for sustainability reporting. It also specifies the requirements and reporting principles that organizations must comply with to report in accordance with the GRI Standards. GRI 1 is the first Standard that organizations should consult to understand how to report using the GRI Standards.', 'GRI 1: Foundation 2021 introduces the purpose and system of the GRI Sustainability Reporting Standards (GRI Standards) and explains key concepts for sustainability reporting. It also specifies the requirements and reporting principles that organizations must comply with to report in accordance with the GRI Standards. GRI 1 is the first Standard that organizations should consult to understand how to report using the GRI Standards.', 'GRI 1: Foundation 2021 introduces the purpose and system of the GRI Sustainability Reporting Standards (GRI Standards) and explains key concepts for sustainability reporting. It also specifies the requirements and reporting principles that organizations must comply with to report in accordance with the GRI Standards. GRI 1 is the first Standard that organizations should consult to understand how to report using the GRI Standards.', 'GRI', 'climate', 'in_force', '2021-01-01'::date, 'Global Sustainability Standards Board', 'https://globalreporting.org/pdf.ashx?id=12334', ARRAY['sdg13', 'voluntary', 'sdg16', 'gri', 'sdg12', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e994f4ec-eaf6-5ff4-854c-77a006879c32', 'GRI 2: General Disclosures', 'GRI 2: General Disclosures 2021', 'GRI 2: General Disclosures 2021 contains disclosures for organizations to provide information about their reporting practices; activities and workers; governance; strategy, policies, and practices; and stakeholder engagement. This information gives insight into the profile and scale of organizations and provides a context for understanding their impacts.', 'GRI 2: General Disclosures 2021 contains disclosures for organizations to provide information about their reporting practices; activities and workers; governance; strategy, policies, and practices; and stakeholder engagement. This information gives insight into the profile and scale of organizations and provides a context for understanding their impacts.', 'GRI 2: General Disclosures 2021 contains disclosures for organizations to provide information about their reporting practices; activities and workers; governance; strategy, policies, and practices; and stakeholder engagement. This information gives insight into the profile and scale of organizations and provides a context for understanding their impacts.', 'GRI', 'climate', 'in_force', '2021-01-01'::date, 'Global Reporting Initiative', 'https://www.globalreporting.org/pdf.ashx?id=12358', ARRAY['sdg8', 'regulations', 'sdg17', 'sdg16', 'gri', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8917919e-f1c2-5653-bc6c-d7173161fba0', 'GRI 3: Material Topics', 'GRI 3: Material Topics 2021', 'GRI 3: Material Topics 2021 provides step-by-step guidance for organizations on how to determine material topics. It also explains how the Sector Standards are used in this process. Material topics are topics that represent an organization’s most significant impacts on the economy, environment, and people, including impacts on their human rights. GRI 3 also contains disclosures for organizations to report information about their process of determining material topics, their list of material topics, and how they manage each of their material topics.', 'GRI 3: Material Topics 2021 provides step-by-step guidance for organizations on how to determine material topics. It also explains how the Sector Standards are used in this process. Material topics are topics that represent an organization’s most significant impacts on the economy, environment, and people, including impacts on their human rights. GRI 3 also contains disclosures for organizations to report information about their process of determining material topics, their list of material topics, and how they manage each of their material topics.', 'GRI 3: Material Topics 2021 provides step-by-step guidance for organizations on how to determine material topics. It also explains how the Sector Standards are used in this process. Material topics are topics that represent an organization’s most significant impacts on the economy, environment, and people, including impacts on their human rights. GRI 3 also contains disclosures for organizations to report information about their process of determining material topics, their list of material topics, and how they manage each of their material topics.', 'GRI', 'climate', 'in_force', '2021-01-01'::date, 'Global Reporting Initiative', 'https://www.globalreporting.org/how-to-use-the-gri-standards/gri-standards-english-language/', ARRAY['regulations', 'sdg16', 'gri', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('523f51bd-1658-5077-97ce-ef22acb8c34c', 'GRI 11: Oil and Gas Sector', 'GRI 11: Oil and Gas Sector 2021', 'GRI 11: Oil and Gas Sector 2021 provides information for organizations in the oil and gas sector about their likely material topics. These topics are likely to be material for organizations in the oil and gas sector on the basis of the sector’s most significant impacts on the economy, environment, and people, including on their human rights.  GRI 11 also contains a list of disclosures for organizations in the oil and gas sector to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI 11: Oil and Gas Sector 2021 provides information for organizations in the oil and gas sector about their likely material topics. These topics are likely to be material for organizations in the oil and gas sector on the basis of the sector’s most significant impacts on the economy, environment, and people, including on their human rights.  GRI 11 also contains a list of disclosures for organizations in the oil and gas sector to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI 11: Oil and Gas Sector 2021 provides information for organizations in the oil and gas sector about their likely material topics. These topics are likely to be material for organizations in the oil and gas sector on the basis of the sector’s most significant impacts on the economy, environment, and people, including on their human rights.  GRI 11 also contains a list of disclosures for organizations in the oil and gas sector to report in relation to each likely material topic. This includes disclosures from the GRI Topic Standards and other sources.', 'GRI', 'climate', 'in_force', '2021-01-01'::date, 'Global Reporting Initiative', 'https://www.globalreporting.org/media/wu1nugcu/oil-and-gas-faqs-public.pdf', ARRAY['regulations', 'sdg16', 'gri', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('75d862d9-65e0-532a-a651-cce1b9f96562', 'GRI 306: Waste', 'GRI 306: Waste 2020', 'GRI 306: Waste 2020 sets out reporting requirements on the topic of waste. This Standard can be used by an organization of any size, type, sector or geographic location that wants to report on its impacts related to this topic.', 'GRI 306: Waste 2020 sets out reporting requirements on the topic of waste. This Standard can be used by an organization of any size, type, sector or geographic location that wants to report on its impacts related to this topic.', 'GRI 306: Waste 2020 sets out reporting requirements on the topic of waste. This Standard can be used by an organization of any size, type, sector or geographic location that wants to report on its impacts related to this topic.', 'GRI', 'climate', 'in_force', '2020-01-01'::date, 'KPMG International', 'https://assets.kpmg.com/content/dam/kpmg/th/pdf/2020/11/presentation-webcast-gri-306-waste-2020.pdf', ARRAY['regulations', 'gri', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
