INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5c9bd527-5741-56b0-9820-48a881239832', 'GRI 101: Foundation', 'GRI 101: Foundation 2016', 'GRI 101: Foundation applies to any organization that wants to use the GRI Standards to report about its economic, environmental, and/or social impacts. Therefore, this Standard is applicable to: an organization that intends to prepare a sustainability report in accordance with the GRI Standards; or an organization that intends to use selected GRI Standards, or parts of their content, to report on impacts related to specific economic, social, and/or environmental topics (e.g., to report on emissions only). GRI 101 can be used by an organization of any size, type, sector, or geographic location.', 'GRI 101: Foundation applies to any organization that wants to use the GRI Standards to report about its economic, environmental, and/or social impacts. Therefore, this Standard is applicable to: an organization that intends to prepare a sustainability report in accordance with the GRI Standards; or an organization that intends to use selected GRI Standards, or parts of their content, to report on impacts related to specific economic, social, and/or environmental topics (e.g., to report on emissions only). GRI 101 can be used by an organization of any size, type, sector, or geographic location.', 'GRI 101: Foundation applies to any organization that wants to use the GRI Standards to report about its economic, environmental, and/or social impacts. Therefore, this Standard is applicable to: an organization that intends to prepare a sustainability report in accordance with the GRI Standards; or an organization that intends to use selected GRI Standards, or parts of their content, to report on impacts related to specific economic, social, and/or environmental topics (e.g., to report on emissions only). GRI 101 can be used by an organization of any size, type, sector, or geographic location.', 'GRI', 'climate', 'in_force', '2018-01-01'::date, 'GRI', 'https://www.ekvilib.org/wp-content/uploads/2018/03/GRI-standardi-2016.pdf', ARRAY['sdg13', 'regulations', 'gri', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
