INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e20a37b8-6a52-5749-b8e3-bb7567424b1d', 'GRI In Focus: Addressing Investor Needs in Business Reporting', 'In Focus: Addressing Investor Needs in Business Reporting on the SDGs', 'This document features recommendations on how corporate reporting on the Sustainable Development Goals (SDGs) can best address investors’ information needs. By helping inform investors'' decision-making process, corporate SDG reporting can stimulate more investment in sustainable business solutions to help advance the Global Goals.', 'This document features recommendations on how corporate reporting on the Sustainable Development Goals (SDGs) can best address investors’ information needs. By helping inform investors'' decision-making process, corporate SDG reporting can stimulate more investment in sustainable business solutions to help advance the Global Goals.', 'This document features recommendations on how corporate reporting on the Sustainable Development Goals (SDGs) can best address investors’ information needs. By helping inform investors'' decision-making process, corporate SDG reporting can stimulate more investment in sustainable business solutions to help advance the Global Goals.', 'GRI', 'climate', 'in_force', '2018-01-01'::date, 'UN SDGs', 'https://sdgs.un.org/sites/default/files/2021-07/GRI%20-%20Addressing%20investors%20needs.pdf', ARRAY['sdg13', 'other sustainability policy', 'voluntary', 'sdg16', 'gri', 'sdg12', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
